/bin/zsh -lc "python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
class FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.nodes = []
    def handle_starttag(self, tag, attrs):
        self.nodes.append((tag, dict(attrs)))
p = FormParser()
p.feed(Path('index.html').read_text())
ids = [attrs['id'] for _, attrs in p.nodes if 'id' in attrs]
assert len(ids) == len(set(ids)), 'Duplicate IDs'
for tag, attrs in p.nodes:
    for key in ('aria-describedby', 'aria-labelledby'):
        for target in attrs.get(key, '').split():
            assert target in ids, f'Missing {key} target: {target}'
    if tag == 'label':
        assert attrs['for'] in ids
    assert int(attrs.get('tabindex', '0')) <= 0, 'Positive tabindex'
for field in ('equipment', 'return-date'):
    assert any(tag == 'label' and attrs.get('for') == field for tag, attrs in p.nodes)
    assert any(attrs.get('id') == field and 'required' in attrs for _, attrs in p.nodes)
print('HTML checks passed: unique IDs, labels, required fields, ARIA targets, no positive tabindex.')
PY"

